reactiveclass Ping(5) {
	knownrebecs { Pong pong; }
	statevars { int count; int state; }

	Ping() {
		count = 0;
		state = 0;
	}

	msgsrv initial() {
		self.StartMessage();
	}

	msgsrv StartMessage() {
		if (state == 0) {
			pong.PingMessage();
		}
	}

	msgsrv PongMessage() {
		if (state == 0) {
			count = count + 1;
			if (count >= 10) {
				pong.StopMessage();
				state = 1;
			} else {
				pong.PingMessage();
			}
		}
	}
}

